'use strict';

// Per-routine spec access and the signature projections (CONVENTIONS S1–S4,
// D1–D3, D5c, W2). The spec (spec/<routine>.json, generated by bin/gen_spec)
// declares the parameters and their roles; this module turns that into the
// three JavaScript signatures. It is the single place those projections live.
//
//   base(spec)     base.js / strided.js parameter list (offset form, S1/S3)
//   strided(spec)  <routine>.js parameter list (S4, D1–D3)

var path = require( 'path' );
var fs = require( 'fs' );

var ROOT = path.join( __dirname, '..', '..' );
var SPEC_DIR = path.join( ROOT, 'spec' );

function load( routine ) {
	var file = path.join( SPEC_DIR, routine + '.json' );
	if ( !fs.existsSync( file ) ) {
		return null;
	}
	return JSON.parse( fs.readFileSync( file, 'utf8' ) );
}

// Suffix used in stride/offset names (S2, W2): `x` → `X`, `IPIV` → `IPIV`,
// `WORK` → `Work`, `IWORK` → `IWork`, `RWORK` → `RWork`.
function suffix( p ) {
	var m;
	if ( p.role === 'workspace' && ( m = /^([A-Za-z]?)work(.*)$/i.exec( p.name ) ) ) {
		return m[ 1 ].toUpperCase() + 'Work' + m[ 2 ].toLowerCase();
	}
	if ( p.name === p.name.toLowerCase() ) {
		return p.name.charAt( 0 ).toUpperCase() + p.name.slice( 1 );
	}
	return p.name;
}

// A 2-D workspace is 2-D only when it has an LD argument (dtrsna's
// `WORK( LDWORK, N+6 )`); one whose leading extent is computed (dsytri2x's
// `WORK( N+NB+1, * )`) is caller-owned scratch like any other (D2).
function isTwoD( p ) {
	return p.role === 'matrix' || p.role === 'banded' || ( p.role === 'workspace' && p.dims && p.dims.length === 2 && !!p.ld );
}

function isOneD( p ) {
	return !isTwoD( p ) && ( p.role === 'vector' || p.role === 'index' || p.role === 'packed' || p.role === 'workspace' );
}

// Complex out/inout scalars cross as `x, offsetX` (S1), as does a scalar
// marked `element` (callers pass an element of their own array; S10). Every
// other scalar output is a single caller-provided length-1 array (S10).
function isOffsetScalar( p ) {
	return p.role === 'scalar' && ( p.element === true || ( p.intent !== 'in' && /^complex/.test( p.dtype ) ) );
}

// Groups of base.js parameter names, one group per spec param.
// Params in JS order: Fortran order unless the spec's `jsOrder` (an
// override) says otherwise.
function ordered( spec ) {
	var rank = {};
	if ( !spec.jsOrder ) {
		return spec.params;
	}
	spec.jsOrder.forEach( function each( n, i ) {
		rank[ n ] = i;
	});
	return spec.params.slice().sort( function s( a, b ) {
		var ra = ( a.fortran in rank ) ? rank[ a.fortran ] : spec.jsOrder.length + a.position;
		var rb = ( b.fortran in rank ) ? rank[ b.fortran ] : spec.jsOrder.length + b.position;
		return ra - rb;
	});
}

function baseGroups( spec ) {
	var groups = [];
	var taken = {};
	ordered( spec ).forEach( function each( p ) {
		var s;
		var g;
		switch ( p.role ) {
		case 'ld':
		case 'inc':
		case 'lwork':
			g = [];
			break;
		case 'info':
			// INFO is the return value (S11); an in/out INFO also enters as `infoIn`.
			g = ( p.intent === 'out' ) ? [] : [ p.name ];
			break;
		case 'result':
			g = [ p.name, 'offset' + suffix( p ) ];
			break;
		default:
			s = suffix( p );
			if ( isTwoD( p ) ) {
				g = [ p.name, 'stride' + s + '1', 'stride' + s + '2', 'offset' + s ];
			} else if ( isOneD( p ) ) {
				g = [ p.name, 'stride' + s, 'offset' + s ];
			} else if ( isOffsetScalar( p ) ) {
				g = [ p.name, 'offset' + s ];
			} else {
				g = [ p.name ];
			}
		}
		groups.push( { 'param': p, 'names': g } );
		g.forEach( function each( n ) {
			taken[ n.toLowerCase() ] = ( taken[ n.toLowerCase() ] || 0 ) + 1;
		});
	});
	// S2: on a stride-name collision, a 1-D array takes a trailing `1`
	// (`strideQ2` of 1-D Q2 vs `strideQ2` of 2-D Q → `strideQ21`).
	groups.forEach( function each( g ) {
		if ( g.names.length === 3 && taken[ g.names[ 1 ].toLowerCase() ] > 1 ) {
			g.names = [ g.names[ 0 ], g.names[ 1 ] + '1', g.names[ 2 ] ];
		}
	});
	return groups;
}

function base( spec ) {
	return baseGroups( spec ).reduce( function r( acc, g ) {
		return acc.concat( g.names );
	}, [] );
}

// Does the routine take a non-workspace matrix (D1: `order` iff LD or packed)?
function takesOrder( spec ) {
	return spec.params.some( function some( p ) {
		return p.role === 'matrix' || p.role === 'banded' || ( p.role === 'packed' && p.format === 'packed' );
	});
}

function wrapper( spec ) {
	var out = [];
	baseGroups( spec ).forEach( function each( g ) {
		var p = g.param;
		if ( g.names.length === 4 ) {
			out.push( p.name, 'LD' + p.name.toUpperCase() );    // D2: matrix → A, LDA
		} else if ( g.names.length === 3 ) {
			if ( p.role === 'workspace' || ( p.role === 'packed' && p.format === 'packed' ) ) {
				out.push( p.name );                              // D2/D5c: no stride
			} else {
				out.push( p.name, g.names[ 1 ] );                // keep stride, drop offset (D3)
			}
		} else if ( g.names.length === 2 ) {
			out.push( p.name );                                  // complex scalar / result: drop offset
		} else {
			out.push.apply( out, g.names );
		}
	});
	return takesOrder( spec ) ? [ 'order' ].concat( out ) : out;
}

var OPTIONS = null;

// The strings an input option accepts, in spec/options.json order: the
// values of its spec enum check (what the reference accepts for this
// routine), else every value of its options family (plus its `other`),
// else null.
function optionValues( spec, fortran ) {
	var checked = null;
	var fam = null;
	var all;
	var i;
	( spec.checks || [] ).forEach( function each( c ) {
		if ( c.kind === 'enum' && c.param === fortran && c.values ) {
			checked = c.values;
		}
	});
	if ( OPTIONS === null ) {
		OPTIONS = JSON.parse( fs.readFileSync( path.join( SPEC_DIR, 'options.json' ), 'utf8' ) ).families;
	}
	for ( i = 0; i < OPTIONS.length && !fam; i++ ) {
		if ( OPTIONS[ i ].params.indexOf( fortran ) >= 0 && ( !OPTIONS[ i ].routines || new RegExp( OPTIONS[ i ].routines ).test( spec.routine ) ) ) {
			fam = OPTIONS[ i ];
		}
	}
	all = ( fam ) ? Object.keys( fam.values ).map( function v( k ) {
		return fam.values[ k ];
	}).concat( ( fam.other ) ? [ fam.other ] : [] ).filter( function u( v, j, a ) {
		return a.indexOf( v ) === j;
	}) : [];
	if ( checked ) {
		return all.filter( function f( v ) {
			return checked.indexOf( v ) >= 0;
		}).concat( checked.filter( function f( v ) {
			return all.indexOf( v ) < 0;
		}) );
	}
	return ( fam ) ? all : null;
}

module.exports = {
	'optionValues': optionValues,
	'SPEC_DIR': SPEC_DIR,
	'load': load,
	'base': base,
	'strided': base,
	'wrapper': wrapper,
	'takesOrder': takesOrder,
	'baseGroups': baseGroups
};
